input.newString:
const keys = { ArrowLeft: false, ArrowRight: false, ArrowUp: false };
// Audio setup
const audioCtx = new (window.AudioContext || window.webkitAudioContext)();
let thrustOsc = null;
function playThrust(){
  if (thrustOsc) return;
  const osc = audioCtx.createOscillator();
  const gain = audioCtx.createGain();
  osc.type = 'sawtooth';
  osc.frequency.setValueAtTime(200, audioCtx.currentTime);
  gain.gain.setValueAtTime(0.05, audioCtx.currentTime);
  osc.connect(gain).connect(audioCtx.destination);
  osc.start();
  thrustOsc = {osc, gain};
}
function stopThrust(){
  if (!thrustOsc) return;
  thrustOsc.gain.gain.exponentialRampToValueAtTime(0.001, audioCtx.currentTime + 0.1);
  thrustOsc.osc.stop(audioCtx.currentTime + 0.1);
  thrustOsc = null;
}
function playCollision(){
  const osc = audioCtx.createOscillator();
  const gain = audioCtx.createGain();
  osc.type = 'square';
  osc.frequency.setValueAtTime(100, audioCtx.currentTime);
  gain.gain.setValueAtTime(0.2, audioCtx.currentTime);
  osc.connect(gain).connect(audioCtx.destination);
  osc.start();
  osc.stop(audioCtx.currentTime + 0.2);
}
function playGameOver(){
  const osc = audioCtx.createOscillator();
  const gain = audioCtx.createGain();
  osc.type = 'triangle';
  osc.frequency.setValueAtTime(50, audioCtx.currentTime);
  gain.gain.setValueAtTime(0.3, audioCtx.currentTime);
  osc.connect(gain).connect(audioCtx.destination);
  osc.start();
  osc.stop(audioCtx.currentTime + 0.5);
}
window.addEventListener('keydown', e => {
  if (e.key in keys) {
    keys[e.key] = true;
    if (e.key === 'ArrowUp') playThrust();
  }
});
window.addEventListener('keyup', e => {
  if (e.key in keys) {
    keys[e.key] = false;
    if (e.key === 'ArrowUp') stopThrust();
  }
});

