for (const a of asteroids) {
  const dx = ship.x - a.x;
  const dy = ship.y - a.y;
  const dist = Math.hypot(dx, dy);
  if (dist < ship.radius + a.radius) {
    // Collision sound and game over cue
    playCollision();
    playGameOver();
    gameOver = true;
    break;
  }
}

